actions.script:
// 1. Sanitize <container-row> and <container-col> to Quasar Flex classes
if (cleanedXml.contains("<container-row") || cleanedXml.contains("<container-col")) {
    if (autoCorrect) {
        cleanedXml = cleanedXml.replaceAll(/<container-row\b[^>]*>/, '<container style="row q-col-gutter-md">')
        cleanedXml = cleanedXml.replaceAll(/<\/container-row>/, '</container>')
        cleanedXml = cleanedXml.replaceAll(/<container-col\b[^>]*md="(\d+)"[^>]*>/, '<container style="col-12 col-md-$1">')
        cleanedXml = cleanedXml.replaceAll(/<container-col\b[^>]*>/, '<container style="col-12 col-md">')
        cleanedXml = cleanedXml.replaceAll(/<\/container-col>/, '</container>')
    } else {
        errorList.add("Forbidden tags <container-row> or <container-col> detected.")
    }
}

// 2. Sanitize deprecated <subscreens-tabs> to <subscreens-menu type="tab"/>
if (cleanedXml.contains("<subscreens-tabs")) {
    if (autoCorrect) {
        cleanedXml = cleanedXml.replaceAll(/<subscreens-tabs\b([^>]*)\/>/, '<subscreens-menu$1 type="tab"/>')
    } else {
        errorList.add("Deprecated tag <subscreens-tabs> detected. Use <subscreens-menu type=\"tab\"/>.")
    }
}

// 3. Sanitize invalid field containers <container name="display"/>
if (cleanedXml.contains('<container name="display"/>') || cleanedXml.contains('<container name="display">')) {
    if (autoCorrect) {
        cleanedXml = cleanedXml.replaceAll(/<container name="display"\s*\/?>/, '<display/>')
        cleanedXml = cleanedXml.replaceAll(/<\/container>/, '')
    } else {
        errorList.add("Invalid field container '<container name=\"display\"/>' detected. Use '<display/>'.")
    }
}

// 4. Ensure <subscreens> has default-item declared
if (cleanedXml.contains("<subscreens>") || (cleanedXml.contains("<subscreens ") && !cleanedXml.contains("default-item="))) {
    java.util.regex.Matcher itemMatcher = (cleanedXml =~ /<subscreens-item\s+name="([^"]+)"/)
    if (itemMatcher.find()) {
        String firstItem = itemMatcher.group(1)
        cleanedXml = cleanedXml.replaceFirst(/<subscreens(\s*)/, '<subscreens default-item="' + firstItem + '"$1')
    } else {
        errorList.add("Missing default-item on <subscreens> tag.")
    }
}

// 5. Xerces XML Parse Validation
try {
    javax.xml.parsers.DocumentBuilderFactory dbf = javax.xml.parsers.DocumentBuilderFactory.newInstance()
    dbf.setNamespaceAware(true)
    javax.xml.parsers.DocumentBuilder db = dbf.newDocumentBuilder()
    db.parse(new org.xml.sax.InputSource(new java.io.StringReader(cleanedXml)))
} catch (Exception e) {
    errorList.add("XML Syntax/Schema Parse Error: " + e.getMessage())
}
